-- Data Analysis Learning Path | SQLite starter database
-- Run in a NEW, EMPTY SQLite database. Dataset is fictional.

BEGIN TRANSACTION;
CREATE TABLE customers(customer_id TEXT PRIMARY KEY,customer_name TEXT NOT NULL,segment TEXT NOT NULL,region TEXT NOT NULL,signup_date TEXT NOT NULL);
CREATE TABLE orders(order_id TEXT PRIMARY KEY,order_date TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(customer_id),region TEXT NOT NULL,category TEXT NOT NULL,product TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price REAL NOT NULL,unit_cost REAL NOT NULL,discount_pct REAL NOT NULL,status TEXT NOT NULL,sales_rep TEXT NOT NULL);
CREATE TABLE targets(month_start TEXT NOT NULL,region TEXT NOT NULL,sales_target REAL NOT NULL,PRIMARY KEY(month_start,region));
CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_orders_customer ON orders(customer_id);
COMMIT;
